  "You do not have permission to view authentication settings.": ["Anda tidak punya izin untuk melihat pengaturan autentikasi."],
  "You do not have permission to view blog pages.": ["Anda tidak punya izin untuk melihat halaman blog."],
  "You do not have permission to view blog posts.": ["Anda tidak punya izin untuk melihat postingan blog."],
  "You do not have permission to view blog settings.": ["Anda tidak punya izin untuk melihat pengaturan blog."],
